package basics_practice;

public class Compare_Strings {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String s="hello";
		String ss="HELLOo";
		String a="hello";
		System.out.println(s.equals(ss));
		System.out.println(s==ss);
		System.out.println(s.equals(a));

	}

}
